 "content": "def transform(grid):
    # Shift the monochrome objects into a compact stack, preserving the
    # observed left-to-right order and each object's shape.
    h, w = len(grid), len(grid[0])
    objs=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==0 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            objs.append((minc,color,cells,minr,minc,maxr,maxc))
    objs.sort(key=lambda q:q[0])
    out=[[0]*w for _ in range(h)]
    y=x=0
    for _,color,cells,minr,minc,maxr,maxc in objs:
        for r,c in cells:
            yy=y+r-minr; xx=x+c-minc
            if yy<h and xx<w:
                out[yy][xx]=color
        y += maxr-minr
        x += maxc-minc
    return out
